// from storage. FirstLoad is not serialized, so the clone GetConfig returns
// always reports false.
func (d *Downloader) IsFirstLoad() bool {
	d.configLock.RLock()
	defer d.configLock.RUnlock()
	return d.cfg.FirstLoad
}

