577	func TestDownloader_StaleStartGenerationCannotRestartTask(t *testing.T) {
578		manager := &generationTestManager{}
579		downloader := NewDownloader(&DownloaderConfig{FetchManagers: []fetcher.FetcherManager{manager}})
580		if err := downloader.Setup(); err != nil {
581			t.Fatal(err)
582		}
583		defer downloader.Clear()
584		downloader.cfg.MaxRunning = 0
585	
586		id, err := downloader.CreateDirect(&base.Request{URL: "generation://test"}, &base.Options{
587			Path: t.TempDir(),
588			Name: "generation.bin",
589		})
590		if err != nil {
591			t.Fatal(err)
592		}
593		task := downloader.GetTask(id)
594		if task == nil || task.Status != base.DownloadStatusWait {
595			t.Fatalf("expected queued task, got %#v", task)
596		}
597	
598		// Hold task.lock so the first Start, its Pause handler, and the second Start
599		// are all queued. Only the newest start generation may reach Fetcher.Start.
600		task.lock.Lock()
601		downloader.cfg.MaxRunning = 1
602		if err := downloader.Continue(&TaskFilter{IDs: []string{id}}); err != nil {
603			t.Fatal(err)
604		}
605		pauseDone := make(chan error, 1)
606		go func() {
607			pauseDone <- downloader.Pause(&TaskFilter{IDs: []string{id}})
608		}()
609		deadline := time.Now().Add(2 * time.Second)
610		for downloader.taskStatus(task) != base.DownloadStatusPause && time.Now().Before(deadline) {
611			time.Sleep(5 * time.Millisecond)
612		}
613		if downloader.taskStatus(task) != base.DownloadStatusPause {
614			t.Fatal("Pause did not update task status")
615		}
616		if err := downloader.Continue(&TaskFilter{IDs: []string{id}}); err != nil {
617			t.Fatal(err)
618		}
619		task.lock.Unlock()
