25	func changeValue(p any, v any) {
26		if v == nil {
27			return
28		}
29		rp := reflect.ValueOf(p)
30		rv := reflect.ValueOf(v)
31		if rv.Kind() == reflect.Slice {
32			if rv.Len() == 0 {
33				return
34			}
35			// get underlying type
36			tp := reflect.TypeOf(p).Elem().Elem()
37			for i := 0; i < rv.Len(); i++ {
38				// convert to underlying type
39				vv := rv.Index(i).Elem().Convert(tp)
40				rp.Elem().Set(reflect.Append(rp.Elem(), vv))
41			}
42		} else if rv.Kind() == reflect.Ptr {
43			rp.Elem().Set(rv.Elem())
